import { AsyncLocalStorage } from 'node:async_hooks';
export const tenantStore = new AsyncLocalStorage();
export function tenantMiddleware(req, res, next) {
  const tenant = req.headers['x-tenant'] || req.subdomains[0];
  if (!tenant) return res.status(400).send('no tenant');
  tenantStore.run({ tenantId: tenant }, () => next());
}
export const currentTenant = () => tenantStore.getStore()?.tenantId;
